const allItems = $input.all();
let articles = [];
allItems.forEach(item => {
    const json = item.json;
    const title = json.title || json.name || '';
    const summary = json.summary || json.content || json.description || json.contentSnippet || '';
    if (title) articles.push({ title, summary: summary.substring(0, 200) });
});
const seen = new Set();
articles = articles.filter(a => {
    const key = a.title.toLowerCase().substring(0, 50);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
});
articles = articles.slice(0, 25);
const newsText = articles.map((a, i) =>
    (i + 1) + '. ' + a.title + (a.summary ? ' -- ' + a.summary.substring(0, 150) : '')
).join('\n');
const systemPrompt = [
    'You are an expert financial news analyst for XAUUSD (Gold) trading. Output STRICT JSON ONLY.',
    '',
    'CONTEXT RULES:',
    '- War/conflict/escalation = BULLISH for gold (safe haven)',
    '- Ceasefire/peace/de-escalation = BEARISH for gold',
    '- Fed hawkish/rate hike = BEARISH. Fed dovish/rate cut/inflation = BULLISH',
    '- Dollar weakness = BULLISH. Dollar strength = BEARISH',
    '- Market panic/crash = BULLISH. Risk-on/stocks rally = BEARISH',
    '- Nuclear/major military = EXTREMELY BULLISH',
    '- Understand context: ceasefire talks COLLAPSE = BULLISH (not bearish)',
    '',
    'VOLATILITY: EXTREME(sl_mult=2.0,min_rr=2.5,min_sl=20) HIGH(1.5,2.0,15) ELEVATED(1.2,2.0,12) NORMAL(1.0,2.0,8)',
    '',
    'JSON OUTPUT FORMAT:',
    '{"news_sentiment":"BULLISH|SLIGHTLY_BULLISH|NEUTRAL|SLIGHTLY_BEARISH|BEARISH",',
    '"volatility_level":"NORMAL|ELEVATED|HIGH|EXTREME",',
    '"sl_multiplier":1.0,"min_rr":2.0,"min_sl_distance":8,',
    '"extreme_caution":false,"extreme_caution_reason":"",',
    '"war_news":"top 3 pipe-separated or No war news",',
    '"fed_news":"top 2 pipe-separated or No Fed news",',
    '"gold_news":"top 3 pipe-separated or No gold news",',
    '"all_headlines":"top 6 most impactful double-pipe-separated",',
    '"sentiment_reasoning":"2-3 sentences on market mood and gold direction",',
    '"bull_score":0,"bear_score":0,',
    '"war_news_count":0,"fed_news_count":0,"gold_news_count":0,"ceasefire_news_count":0}'
].join('\n');
const userPrompt = 'Analyze these headlines for XAUUSD impact:\n\n' + newsText + '\n\nTime: ' + new Date().toISOString();
return [{
    json: {
        request_body: {
            model: 'deepseek/deepseek-chat',
            messages: [
                { role: 'system', content: systemPrompt },
                { role: 'user', content: userPrompt }
            ],
            temperature: 0.2,
            max_tokens: 800
        },
        total_articles: articles.length,
        fetched_at: new Date().toISOString()
    }
}];

const item = $input.first();
const json = item.json;
const defaults = {
    news_sentiment: 'NEUTRAL', volatility_level: 'NORMAL', sl_multiplier: 1.0, min_rr: 2.0, min_sl_distance: 8,
    extreme_caution: false, extreme_caution_reason: '',
    war_news: 'News AI unavailable', fed_news: 'News AI unavailable', gold_news: 'News AI unavailable',
    all_headlines: 'News AI unavailable', sentiment_reasoning: 'AI news analysis failed. Using neutral defaults.',
    bull_score: 0, bear_score: 0, war_news_count: 0, fed_news_count: 0, gold_news_count: 0, ceasefire_news_count: 0,
    total_articles: 0, news_fetched_at: new Date().toISOString(), ai_powered: false
};
let aiText = '';
try {
    if (json.choices && json.choices[0] && json.choices[0].message) {
        aiText = json.choices[0].message.content || '';
    }
} catch (e) { return [{ json: defaults }]; }
if (!aiText) { return [{ json: defaults }]; }
let cleaned = aiText.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
const firstBrace = cleaned.indexOf('{');
const lastBrace = cleaned.lastIndexOf('}');
let data = {};
if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    try { data = JSON.parse(cleaned.substring(firstBrace, lastBrace + 1)); }
    catch (e) { defaults.extreme_caution_reason = 'Parse error: ' + e.message; return [{ json: defaults }]; }
} else { return [{ json: defaults }]; }
const validS = ['BULLISH', 'SLIGHTLY_BULLISH', 'NEUTRAL', 'SLIGHTLY_BEARISH', 'BEARISH'];
const validV = ['NORMAL', 'ELEVATED', 'HIGH', 'EXTREME'];
const sentiment = validS.includes(data.news_sentiment) ? data.news_sentiment : 'NEUTRAL';
const volatility = validV.includes(data.volatility_level) ? data.volatility_level : 'NORMAL';
const slMult = Math.min(Math.max(parseFloat(data.sl_multiplier) || 1.0, 1.0), 2.5);
const minRR = Math.min(Math.max(parseFloat(data.min_rr) || 2.0, 1.5), 3.0);
const minSL = Math.min(Math.max(parseInt(data.min_sl_distance) || 8, 5), 30);
let totalArticles = 0, fetchedAt = new Date().toISOString();
try { const p = $('Prepare News for AI').first(); totalArticles = p.json.total_articles || 0; fetchedAt = p.json.fetched_at || fetchedAt; } catch (e) { }
return [{
    json: {
        news_sentiment: sentiment, volatility_level: volatility, sl_multiplier: slMult, min_rr: minRR, min_sl_distance: minSL,
        extreme_caution: !!data.extreme_caution, extreme_caution_reason: data.extreme_caution_reason || '',
        war_news: data.war_news || 'No war news', fed_news: data.fed_news || 'No Fed news',
        gold_news: data.gold_news || 'No gold news', all_headlines: data.all_headlines || 'No headlines',
        sentiment_reasoning: data.sentiment_reasoning || '', bull_score: parseInt(data.bull_score) || 0,
        bear_score: parseInt(data.bear_score) || 0, war_news_count: parseInt(data.war_news_count) || 0,
        fed_news_count: parseInt(data.fed_news_count) || 0, gold_news_count: parseInt(data.gold_news_count) || 0,
        ceasefire_news_count: parseInt(data.ceasefire_news_count) || 0,
        total_articles: totalArticles, news_fetched_at: fetchedAt, ai_powered: true
    }
}];

const allItems=$input.all();
let price=null,newsData={};
allItems.forEach(item=>{
  const json=item.json;
  if(json.price!==undefined) price=json.price;
  if(json.news_sentiment!==undefined) newsData=json;
});

// === PHILIPPINE TIME & SESSION DETECTION ===
const now = new Date();
const utcHour = now.getUTCHours();
const utcMinute = now.getUTCMinutes();
const phtHour = (utcHour + 8) % 24;
const phtMinute = utcMinute;
const phtTimeStr = String(phtHour).padStart(2,'0') + ':' + String(phtMinute).padStart(2,'0');
const phtPeriod = phtHour >= 12 ? 'PM' : 'AM';
const phtHour12 = phtHour === 0 ? 12 : (phtHour > 12 ? phtHour - 12 : phtHour);
const phtTime12 = phtHour12 + ':' + String(phtMinute).padStart(2,'0') + ' ' + phtPeriod;
const phtDate = new Date(now.getTime() + 8*60*60*1000);
const phtDay = phtDate.getUTCDay();
const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const phtDayName = dayNames[phtDay];
const phtDateStr = phtDate.toISOString().split('T')[0];

let sessions = [];
let sessionWarnings = [];
let sessionTips = [];

if (utcHour >= 0 && utcHour < 8) sessions.push('ASIAN');
if (utcHour >= 7 && utcHour < 16) sessions.push('LONDON');
if (utcHour >= 13 && utcHour < 22) sessions.push('NEW_YORK');
if (utcHour >= 13 && utcHour < 16) sessions.push('GOLDEN_HOUR');
if (utcHour >= 22 || utcHour < 0) sessions.push('DANGER_ZONE');

const activeSession = sessions.length > 0 ? sessions.join(' + ') : 'OFF_MARKET';

if (sessions.includes('DANGER_ZONE')) {
  sessionWarnings.push('DANGER ZONE active (PHT 6-8AM). Thin liquidity, erratic spikes.');
  sessionTips.push('Avoid entries. Wait for Asian session open at 8AM PHT.');
}
if (sessions.includes('GOLDEN_HOUR')) {
  sessionTips.push('GOLDEN HOUR active (PHT 9PM-12AM). Peak volatility. Ideal for entries.');
}
if (sessions.includes('ASIAN') && !sessions.includes('LONDON')) {
  sessionTips.push('Asian session (PHT 8AM-4PM). Range-bound, lower volatility. Tighter targets.');
  sessionWarnings.push('Asian session: Gold often consolidates. Breakout trades riskier.');
}
if (sessions.includes('LONDON') && !sessions.includes('NEW_YORK')) {
  sessionTips.push('London session (PHT 3PM-12AM). Strong directional moves.');
}
if (sessions.includes('NEW_YORK') && !sessions.includes('LONDON')) {
  sessionTips.push('NY session only (after London close). Watch for reversals.');
}

let isWeekend = false;
if (phtDay === 0 || phtDay === 6) {
  isWeekend = true;
  sessionWarnings.push('WEEKEND: Market is closed.');
}

return[{json:{
  price:price||'0',
  war_news:newsData.war_news||'No war news',
  fed_news:newsData.fed_news||'No Fed news',
  gold_news:newsData.gold_news||'No gold news',
  all_headlines:newsData.all_headlines||'No headlines',
  news_sentiment:newsData.news_sentiment||'NEUTRAL',
  volatility_level:newsData.volatility_level||'NORMAL',
  sl_multiplier:newsData.sl_multiplier||1.0,
  min_rr:newsData.min_rr||2.0,
  min_sl_distance:newsData.min_sl_distance||8,
  extreme_caution:newsData.extreme_caution||false,
  extreme_caution_reason:newsData.extreme_caution_reason||'',
  total_articles:newsData.total_articles||0,
  war_news_count:newsData.war_news_count||0,
  bull_score:newsData.bull_score||0,
  bear_score:newsData.bear_score||0,
  news_fetched_at:newsData.news_fetched_at||new Date().toISOString(),
  sentiment_reasoning:newsData.sentiment_reasoning||'',
  ai_powered:newsData.ai_powered||false,
  pht_time:phtTime12,
  pht_time_24h:phtTimeStr,
  pht_date:phtDateStr,
  pht_day:phtDayName,
  active_session:activeSession,
  session_warnings:sessionWarnings.join(' | ')||'None',
  session_tips:sessionTips.join(' | ')||'No tips',
  is_weekend:isWeekend,
  is_danger_zone:sessions.includes('DANGER_ZONE'),
  is_golden_hour:sessions.includes('GOLDEN_HOUR')
}}];

const item = $input.first();
const json = item.json;
let rawResponse = '';

if (json.content && json.content.parts && json.content.parts[0] && json.content.parts[0].text) {
    rawResponse = json.content.parts[0].text;
}

const errorResult = {
    chart_analysis_failed: true,
    error: 'No response from Gemini',
    gate1_4h: {trend:'unknown', analysis:'Gemini returned no response'},
    gate2_1h: {aligns_with_4h:false, analysis:'Gemini returned no response'},
    gate3_15m: {liquidity_sweep_occurred:false, mss_confirmed:false, analysis:'Gemini returned no response'},
    overall_chart_summary: 'Chart analysis unavailable'
};

if (!rawResponse) {
    return [{json: errorResult}];
}

let cleaned = rawResponse.replace(/```json\s*/gi, '').replace(/```\s*/g, '');
const firstBrace = cleaned.indexOf('{');
const lastBrace = cleaned.lastIndexOf('}');
let data = {};

if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    try {
        data = JSON.parse(cleaned.substring(firstBrace, lastBrace + 1));
    } catch (e) {
        errorResult.error = 'JSON parse failed: ' + e.message;
        return [{json: errorResult}];
    }
} else {
    errorResult.error = 'No JSON found in response';
    return [{json: errorResult}];
}

return [{json: {
    chart_analysis_failed: false,
    y_axis_mismatch: data.y_axis_mismatch || false,
    y_axis_15m_top: data.y_axis_15m_top || 0,
    y_axis_15m_bottom: data.y_axis_15m_bottom || 0,
    y_axis_15m_current: data.y_axis_15m_current || 0,
    gate1_4h: data.gate1_4h || {},
    gate2_1h: data.gate2_1h || {},
    gate3_15m: data.gate3_15m || {},
    overall_chart_summary: data.overall_chart_summary || 'No summary'
}}];

const item = $input.first();
const json = item.json;

const defaults = {
    asset_name: 'XAUUSD', signal_type: 'WAIT', signal: 'WAIT', confidence: 0,
    entry_price: 0, stop_loss: 0, take_profit: 0, rr_ratio: '0',
    reasoning: 'Qwen Decision Maker returned no response.',
    setup_type: 'No Setup', outcome: 'pending',
    failed_timeframe: 'none', failed_candle: 'Qwen returned no response',
    failed_step: 'none', wait_time: 'Retry in 5 minutes',
    next_step: 'STEP 1: Check API. STEP 2: Re-run. STEP 3: Check logs. STEP 4: Retry.',
    recheck_after: 'Fix API connection',
    news_sentiment: 'UNKNOWN', volatility_level: 'UNKNOWN',
    sl_adjusted: false, sl_multiplier_used: 1,
    news_summary: 'No response', pht_time: '', active_session: '',
    math_check: 'No response'
};

let aiText = '';
try {
    if (json.choices && json.choices[0] && json.choices[0].message) {
        aiText = json.choices[0].message.content || '';
    }
} catch (e) { return [{ json: defaults }]; }

if (!aiText) { return [{ json: defaults }]; }

let cleaned = aiText.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
const firstBrace = cleaned.indexOf('{');
const lastBrace = cleaned.lastIndexOf('}');
let data = {};

if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    try {
        data = JSON.parse(cleaned.substring(firstBrace, lastBrace + 1));
    } catch (e) {
        defaults.reasoning = 'JSON parse failed: ' + e.message;
        defaults.failed_candle = 'Parse error in Qwen response';
        return [{ json: defaults }];
    }
} else {
    return [{ json: defaults }];
}

let signal = (data.signal || 'WAIT').toUpperCase();
const entry = data.entry_price ? parseFloat(data.entry_price) : 0;
const sl = data.stop_loss ? parseFloat(data.stop_loss) : 0;
const tp = data.take_profit ? parseFloat(data.take_profit) : 0;

// === HARD VALIDATION: Override bad signals ===
if (signal !== 'WAIT' && entry > 0 && sl > 0 && tp > 0) {
    const slDist = Math.abs(entry - sl);
    const tpDist = Math.abs(entry - tp);
    const rr = slDist > 0 ? tpDist / slDist : 0;

    let mathFailed = false;
    let mathReason = '';

    // Check minimum SL distance ($15)
    if (slDist < 15) {
        mathFailed = true;
        mathReason += 'SL too close: $' + slDist.toFixed(2) + ' (min $15). ';
    }
    // Check maximum SL distance ($80)
    if (slDist > 80) {
        mathFailed = true;
        mathReason += 'SL too far: $' + slDist.toFixed(2) + ' (max $80). ';
    }
    // Check minimum TP distance ($25)
    if (tpDist < 25) {
        mathFailed = true;
        mathReason += 'TP too close: $' + tpDist.toFixed(2) + ' (min $25). ';
    }
    // Check RR >= 2.0
    if (rr < 2.0) {
        mathFailed = true;
        mathReason += 'RR too low: 1:' + rr.toFixed(1) + ' (min 1:2.0). ';
    }
    // Check direction consistency
    if (signal === 'SELL' && sl < entry) {
        mathFailed = true;
        mathReason += 'SELL but SL below entry (should be above). ';
    }
    if (signal === 'SELL' && tp > entry) {
        mathFailed = true;
        mathReason += 'SELL but TP above entry (should be below). ';
    }
    if (signal === 'BUY' && sl > entry) {
        mathFailed = true;
        mathReason += 'BUY but SL above entry (should be below). ';
    }
    if (signal === 'BUY' && tp < entry) {
        mathFailed = true;
        mathReason += 'BUY but TP below entry (should be above). ';
    }

    // Override to WAIT if math failed
    if (mathFailed) {
        signal = 'WAIT';
        data.failed_timeframe = 'MATH';
        data.failed_candle = 'Math validation failed: ' + mathReason.trim();
        data.failed_step = 'Math Check: ' + mathReason.trim();
        data.reasoning = (data.reasoning || '') + ' [OVERRIDDEN TO WAIT: ' + mathReason.trim() + ']';
        data.wait_time = 'Wait 15-30 min for better price structure with wider SL/TP zones';
        data.confidence_score = Math.min(parseInt(data.confidence_score) || 0, 40);
    }
}

return [{json: {
    asset_name: data.asset_name || 'XAUUSD',
    signal_type: signal,
    signal: signal,
    confidence: parseInt(data.confidence_score) || 0,
    entry_price: entry,
    stop_loss: sl,
    take_profit: tp,
    rr_ratio: data.rr_ratio || '0',
    reasoning: data.reasoning || 'No reasoning.',
    setup_type: data.setup_name || 'No Setup',
    outcome: 'pending',
    failed_timeframe: data.failed_timeframe || 'none',
    failed_candle: data.failed_candle || 'none',
    failed_step: data.failed_step || 'none',
    wait_time: data.wait_time || 'none',
    next_step: data.next_step || 'none',
    recheck_after: data.recheck_after || '',
    news_sentiment: data.news_sentiment || 'UNKNOWN',
    volatility_level: data.volatility_level || 'UNKNOWN',
    sl_adjusted: data.sl_adjusted || false,
    sl_multiplier_used: data.sl_multiplier_used || 1,
    news_summary: data.news_summary || 'No news context',
    pht_time: data.pht_time || '',
    active_session: data.active_session || '',
    math_check: data.math_check || ''
}}];
